const fs = require('fs-extra');
const path = require('path');

const outputFolder = "Extensions"
const outputFileName = "IServiceCollection_extensions.lua"


var generated = {}

function buildContent(config) {
    var content = `local module = {}\n\n`
    // loop config
    for (const [key, value] of Object.entries(config)) {
        if (generated[value.Name]) {
            var fullPath1 = path.resolve(generated[value.Name].FilePath);
            var fullPath2 = path.resolve(value.FilePath);
            throw new Error(`存在同名的 TangSengHostBuilder 扩展服务: ${value.Name}, 文件地址: \n${fullPath1}\n${fullPath2} `)
        }
        generated[value.Name] = value

        var parameters = value.Handler.split(",").slice(1)


        var name = value.Name
        if (name.startsWith(".")) {
            name = name.slice(1)
        }

        content += value.Comment
        content += "\n"
        content += `function module:${name}(${parameters.join(",")})\n`;


        // inser "xx" in to first index of parameters
        parameters.unshift("self")

        var args = parameters.map(x => {
            var sp2 = x.split(":")
            return sp2[0]
        }).join(",")

        content += `    local __handler = require(${key})\n`;
        content += `    __handler(${args})\n`;
        content += `    return self\n`;
        content += `end\n\n`;
    }
    content += `return module\n`
    generated = {}
    return content

}



function gen(config, outputManifestPath) {
    // ensure outputFolder
    fs.ensureDirSync(path.join(outputManifestPath, outputFolder));
    var content = buildContent(config)
    fs.writeFileSync(path.join(outputManifestPath, outputFolder, outputFileName), content);
    console.log(`write file ${path.join(outputManifestPath, outputFolder, outputFileName)}`)

}


module.exports = gen;